-- Questões originais: Fernandes e Abreu, Implantando a Governança de TI, 4ª edição, Brasport, 2014.
-- Contexto histórico da edição: COBIT 5, ITIL 2011 e versões de normas nela apresentadas.
-- Não são questões oficiais nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 7: Modelos para Gerenciamento de Serviços de TI — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('6e405472-1d30-55f0-a2e8-989c7ce7dddc', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Governança de TI', 'Fácil', 'O núcleo da ITIL 2011 é organizado em torno de:', '["Cinco estágios do ciclo de vida do serviço.","Quatro fases de compra.","Sete domínios de auditoria.","Somente operação de infraestrutura.","Três níveis de programação."]'::jsonb, 0, 'O ciclo integra estratégia, desenho, transição, operação e melhoria contínua.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b6ede7f1-0b7f-5cac-a393-d04cf344e73d', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Governança de TI', 'Fácil', 'Definir quais serviços oferecer e para quem é preocupação principal de:', '["Estratégia de Serviço.","Transição de Serviço.","Operação de Serviço.","Somente gestão de configuração.","Somente gestão de incidentes."]'::jsonb, 0, 'A estratégia relaciona serviços, clientes e valor para o negócio.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e1424159-383a-5574-93f1-c7d93c0b84dd', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Governança de TI', 'Médio', 'Projetar capacidade, disponibilidade e níveis de serviço pertence principalmente a:', '["Operação de Serviço exclusivamente.","Desenho de Serviço.","Transição de Serviço exclusivamente.","Somente encerramento de contratos.","Estratégia de Serviço exclusivamente."]'::jsonb, 1, 'O desenho prepara serviços e práticas capazes de cumprir requisitos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e56a27bd-af85-57c0-9b67-b20274d7e914', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Governança de TI', 'Médio', 'Levar um serviço novo ao ambiente operacional gerenciado é foco de:', '["Somente relacionamento comercial.","Transição de Serviço.","Estratégia de Serviço.","Somente melhoria contínua.","Apenas gestão financeira."]'::jsonb, 1, 'A transição controla a passagem de serviços novos ou modificados para operação.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f09aece9-32aa-5056-9565-c31f441d67ac', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Governança de TI', 'Fácil', 'Entregar e suportar os serviços no cotidiano é foco de:', '["Operação de Serviço.","Apenas elaboração de portfólio.","Somente desenho.","Somente estratégia.","Exclusivamente testes de aceitação."]'::jsonb, 0, 'A operação sustenta a utilização diária dos serviços.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b5ae215f-1856-5e3a-aa83-a6f12ed42feb', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Governança de TI', 'Médio', 'Qual estágio orienta o aperfeiçoamento continuado da qualidade dos serviços?', '["Somente transição inicial.","Apenas desenho de contratos.","Melhoria Contínua de Serviço.","Exclusivamente estratégia financeira.","Somente operação de rede."]'::jsonb, 2, 'A melhoria deve acompanhar resultados e oportunidades ao longo do ciclo.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('954d6b5f-bc7b-5e2d-809e-84216fd9aab2', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Governança de TI', 'Médio', 'Na ITIL, utilidade e garantia contribuem conjuntamente para:', '["Apenas o tamanho do catálogo.","Somente a quantidade de ativos.","Exclusivamente o preço de aquisição.","O valor do serviço para o cliente.","Somente o número de incidentes."]'::jsonb, 3, 'Utilidade trata da adequação à finalidade; garantia, das condições de uso.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('efea0225-f59d-5d56-a66c-852244448dce', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Governança de TI', 'Médio', 'Um serviço oferece as funções certas, mas fica indisponível no horário necessário. Qual dimensão está prejudicada?', '["Nome do serviço.","Utilidade funcional necessariamente.","Garantia.","Classificação contábil apenas.","Quantidade de fornecedores apenas."]'::jsonb, 2, 'Disponibilidade e capacidade são condições que contribuem para a garantia.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ea94605f-43b0-5165-8f3e-38e08c2d4583', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Governança de TI', 'Médio', 'Manter informações consistentes sobre serviços operacionais é propósito principal de qual processo?', '["Gerenciamento do Catálogo de Serviços.","Gerenciamento de Incidentes.","Gerenciamento de Acesso.","Gerenciamento de Eventos.","Gerenciamento de Problemas."]'::jsonb, 0, 'O catálogo provê informações sobre serviços e sua situação pertinente.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dcdbc5e3-6a1b-5acc-9964-f03add38c1aa', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Governança de TI', 'Médio', 'Restaurar rapidamente um serviço interrompido é objetivo principal de:', '["Coordenação do Desenho.","Gerenciamento do Portfólio.","Gerenciamento Financeiro.","Gerenciamento da Demanda.","Gerenciamento de Incidentes."]'::jsonb, 4, 'O incidente prioriza o restabelecimento do serviço e a redução do impacto.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f927b943-f3f5-5bff-9bd1-7141b74e7bdd', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Governança de TI', 'Médio', 'Investigar a causa de incidentes recorrentes pertence principalmente a:', '["Gerenciamento do Catálogo.","Coordenação do Desenho.","Gerenciamento Financeiro.","Gerenciamento de Acesso.","Gerenciamento de Problemas."]'::jsonb, 4, 'Problemas são tratados para reduzir recorrência e impacto das causas subjacentes.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('11c13a00-3154-5ede-8e3e-91813a257201', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Governança de TI', 'Médio', 'A central de serviços, na estrutura ITIL apresentada, é classificada como:', '["Norma de certificação.","Estágio do ciclo de vida.","Processo financeiro.","Função.","Tipo de contrato externo."]'::jsonb, 3, 'A central é uma função que organiza o contato e o atendimento aos usuários.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('eb4851f4-b1ad-5327-9515-2e4e1a6933f5', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Governança de TI', 'Médio', 'Um acordo sobre metas de serviço com o cliente é tratado por qual processo?', '["Gerenciamento de Acesso.","Gerenciamento de Problemas.","Gerenciamento de Nível de Serviço.","Somente gestão de ativos.","Gerenciamento de Eventos."]'::jsonb, 2, 'O processo negocia, acompanha e revê compromissos de níveis de serviço.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('03b5822f-5d5f-5a2e-9204-3b343ccf64bd', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Governança de TI', 'Difícil', 'Uma correção urgente precisa entrar em produção. Urgência significa dispensar todo controle de mudança?', '["Sim, toda urgência elimina autorização.","Sim, desde que o solicitante seja gerente.","Não; deve seguir tratamento de emergência apropriado.","Sim, se a mudança for pequena.","Não, pois mudanças urgentes nunca são permitidas."]'::jsonb, 2, 'O controle deve considerar risco e urgência sem perder a gestão da mudança.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.1.3, páginas 249–279 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3e841bba-fa57-5d61-a9d9-cf9385557bd0', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Governança de TI', 'Fácil', 'A parte 1 da ISO/IEC 20000 apresentada reúne principalmente:', '["Somente requisitos de hardware.","Somente exemplos de código.","Apenas certificações pessoais.","Requisitos do sistema de gestão de serviços.","Exclusivamente contratos societários."]'::jsonb, 3, 'A parte 1 é a especificação formal do sistema de gestão de serviços.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.2.3, páginas 286–293 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('eb6a0c96-b2e4-5f4a-b7c5-c45761510536', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Governança de TI', 'Médio', 'Qual relação entre ISO/IEC 20000 e ITIL é coerente com o livro?', '["Uma elimina a necessidade de gestão.","Ambas certificam automaticamente qualquer profissional.","São nomes da mesma publicação.","São sempre incompatíveis.","Podem ser utilizadas de forma complementar."]'::jsonb, 4, 'Requisitos normativos e boas práticas podem apoiar a mesma gestão de serviços.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.2.2, páginas 286–293 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('732f0562-e61f-5016-92b4-f616b0c53ae4', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Governança de TI', 'Fácil', 'A constelação CMMI-SVC concentra-se em:', '["Exclusivamente contabilidade financeira.","Melhoria dos processos de serviços.","Apenas diagramas de rede.","Somente aquisição de equipamentos.","Somente desenvolvimento de compiladores."]'::jsonb, 1, 'CMMI for Services oferece diretrizes para organizações prestadoras de serviços.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.3, páginas 299–303 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('697282fc-7805-5a0e-86a4-3ff4c337086a', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Governança de TI', 'Médio', 'No MR-MPS-SV descrito, atingir um nível exige atender a quê?', '["Apenas contratar um auditor.","Resultados dos processos e atributos exigidos para o nível.","Somente comprar uma ferramenta.","Somente comprovar tempo de existência.","Exclusivamente apresentar organograma."]'::jsonb, 1, 'A maturidade envolve processos e sua institucionalização.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.4.3, páginas 304–314 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('696f9bbc-e187-5bf5-b577-6bb898a7481b', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Governança de TI', 'Fácil', 'O USMBOK, conforme apresentado, pode apoiar serviços:', '["Apenas de redes de computadores.","Exclusivamente bancários.","Somente governamentais.","Apenas de desenvolvimento de software.","De diferentes naturezas, inclusive TI."]'::jsonb, 4, 'Seu escopo é o gerenciamento de serviços de forma mais ampla.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.5.1, páginas 316–319 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('37762660-18a4-5a40-bb9c-b8ed458a2582', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Governança de TI', 'Fácil', 'A sigla MOF se refere a qual modelo apresentado no capítulo?', '["Modelo de Operação Fabril.","Método Operacional de Fiscalização.","Modelo Organizacional Financeiro.","Microsoft Operations Framework.","Manual de Orçamento Federal."]'::jsonb, 3, 'O MOF é apresentado como referência para operação e gerenciamento de serviços.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 7, seção 7.6, páginas 320–322 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false)
